PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    parent_id TEXT REFERENCES tasks(id),
    title TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'active',
    first_message TEXT,
    directory TEXT NOT NULL,
    version TEXT,
    git_sha TEXT,
    git_branch TEXT,
    env TEXT,
    costs TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    time_archived INTEGER,
    locked_by TEXT,
    lock_lease_until INTEGER
, approval_config TEXT, message_queue TEXT, task_type TEXT NOT NULL DEFAULT 'normal' CHECK (task_type IN ('normal', 'subtask', 'subagent')), last_error TEXT, is_pinned INTEGER NOT NULL DEFAULT 0, is_unread INTEGER NOT NULL DEFAULT 0);
